import net.mcreator.thermal_shock.entity.PondlerEntity;
import net.minecraft.resources.ResourceLocation;
import software.bernie.geckolib.model.GeoModel;

public class PondlerModel
extends GeoModel<PondlerEntity> {
    public ResourceLocation getAnimationResource(PondlerEntity entity) {
        return new ResourceLocation("thermal_shock", "animations/pondler.animation.json");
    }

    public ResourceLocation getModelResource(PondlerEntity entity) {
        return new ResourceLocation("thermal_shock", "geo/pondler.geo.json");
    }

    public ResourceLocation getTextureResource(PondlerEntity entity) {
        return new ResourceLocation("thermal_shock", "textures/entities/" + entity.getTexture() + ".png");
    }
}
